import {nodeIsRTL,shellKey} from '@/components/nyc-tron/ui/components/shell/shell-keys';
import {MOTION_EASING_PRESETS,validateMotionEasingPresets,type MotionEasingKind,type MotionEasingPreset} from '@/components/nyc-tron/ui/components/forge/motion/motion-easing';
